private String discountReason;

@OneToMany(cascade = CascadeType.ALL, orphanRemoval = true)
@JoinColumn(name = "invoice_id", nullable = false)
@OrderBy("id")
private List<InvoiceLine> lines = new ArrayList<>();

protected Invoice() {
}

/** A new, empty draft for a client, issued and due on the given dates. */
public static Invoice draft(Long clientId, LocalDate issueDate, LocalDate dueDate) {
    Invoice invoice = new Invoice();
    invoice.clientId = clientId;
    invoice.status = InvoiceStatus.DRAFT;
    invoice.issueDate = issueDate;
    invoice.dueDate = dueDate;
    return invoice;
}

/**
 * A new draft for the same client with copies of this invoice's lines and the same invoice
 * discount, issued and due on the given dates. Payments stay with this invoice.
 */
public Invoice duplicate(LocalDate issueDate, LocalDate dueDate) {
    Invoice copy = draft(clientId, issueDate, dueDate);
    copy.discountPct = discountPct;
    copy.discountAmount = discountAmount;
    copy.discountCap = discountCap;
    copy.discountReason = discountReason;
    lines.forEach(line -> copy.lines.add(line.copy()));
    return copy;
}

public Long getId() {
    return id;
public String getDiscountReason() {
    return discountReason;
}

/** Sets why the discount was given; blank is no reason. */
public void setDiscountReason(String discountReason) {
    this.discountReason = discountReason == null || discountReason.isBlank() ? null : discountReason.strip();
}

/** Whether the discount takes off more than a fifth of the subtotal, after any cap, and so needs a reason. */
public boolean discountNeedsReason() {
    return discount().multiply(BigDecimal.valueOf(5)).compareTo(subtotal()) > 0;
}

/** Whether the discount needs a reason but has none. */
public boolean discountLacksReason() {
    return discountNeedsReason() && discountReason == null;
}

/** Sets the percentage taken off the subtotal, clearing any fixed amount; it has already been checked. */
public void setDiscountPct(BigDecimal discountPct) {
    this.discountPct = discountPct;
    this.discountAmount = BigDecimal.ZERO;
}

/** Sets the most taken off the invoice in all, or null for no cap; it has already been checked as money. */
public void setDiscountCap(BigDecimal discountCap) {
    this.discountCap = discountCap;
}

/**
 * Sets a fixed amount taken off the subtotal, clearing any percentage; it has already been checked
 * as money. An amount over the subtotal is refused.
 */
public void setDiscountAmount(BigDecimal discountAmount) {
    if (discountAmount.compareTo(subtotal()) > 0) {
        throw new InvoiceRejectedException("The discount cannot be more than the subtotal of "
                + subtotal().toPlainString() + ".");
    }
    this.discountAmount = discountAmount;
    this.discountPct = BigDecimal.ZERO;
}

public List<InvoiceLine> getLines() {
    return lines;
}

/** Whether lines can still be added: only a draft is still being written. */
public boolean isDraft() {
    return status == InvoiceStatus.DRAFT;
}

/** Whether the invoice has been voided: it no longer counts, takes no payments and cannot be changed. */
public boolean isVoid() {
    return status == InvoiceStatus.VOID;
}

/** Voids a sent invoice. */
public void markVoid() {
    this.status = InvoiceStatus.VOID;
}

/** Marks the invoice sent, issued on the given date and due on the given date. */
public void markSent(LocalDate issueDate, LocalDate dueDate) {
    this.status = InvoiceStatus.SENT;
    this.issueDate = issueDate;
    this.dueDate = dueDate;
}

/** Puts a sent invoice back to draft, so it has to be sent again. */
public void reopen() {
 * clears the other, and the cap (null for none) limits everything taken off, line discounts included. Empty if no such invoice. The values have already been checked; a fixed amount
 * over the subtotal is refused, as is a discount taking off more than a fifth of the subtotal
 * (after the cap) without a reason. A sent invoice with no payments goes back to draft; one with a
 * payment refuses it.
 */
@Transactional
public Optional<Invoice> setDiscount(Long invoiceId, BigDecimal discountPct, BigDecimal discountAmount,
        BigDecimal discountCap, String discountReason) {
    Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
    found.ifPresent(invoice -> {
        boolean reopened = reopenForChange(invoice, "A paid invoice cannot be given a discount.");
        if (discountAmount != null) {
            invoice.setDiscountAmount(discountAmount);
        } else {
            invoice.setDiscountPct(discountPct);
        }
        invoice.setDiscountCap(discountCap);
        invoice.setDiscountReason(discountReason);
        if (invoice.discountLacksReason()) {
            throw new InvoiceRejectedException(
                    "A discount of more than 20% of the subtotal needs a reason.");
        }
        invoices.saveAndFlush(invoice);
        if (reopened) {
            audit.record("INVOICE_REOPENED id=" + invoice.getId());
        }
    });
    return found;
}

/**
 * Readies the invoice for a change: a draft stays as it is; a sent invoice with no payments goes
 * back to draft, to be sent again; an invoice with any payment is refused with the message.
 * Whether it went back to draft.
 */
private boolean reopenForChange(Invoice invoice, String refusal) {
    if (invoice.isDraft()) {
        return false;
    }
    if (invoice.isVoid()) {
        throw new InvoiceRejectedException("A void invoice cannot be changed.");
    }
    if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
        throw new InvoiceRejectedException(refusal);
    }
    invoice.reopen();
    return true;
}

/**
 * Sends a draft invoice, issuing it today and making it due on the client's terms, and records it in the audit; empty if
 * no such invoice. An invoice already sent, with no lines, or whose discount needs a reason but has none, is refused.
 */
@Transactional
public Optional<Invoice> send(Long invoiceId) {
    Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
    found.ifPresent(invoice -> {
        if (invoice.isVoid()) {
            throw new InvoiceRejectedException("A void invoice cannot be sent.");
        }
        if (!invoice.isDraft()) {
            throw new InvoiceRejectedException("This invoice has already been sent.");
        }
        if (invoice.getLines().isEmpty()) {
            throw new InvoiceRejectedException("Add at least one line before sending the invoice.");
        }
        if (invoice.discountLacksReason()) {
            throw new InvoiceRejectedException(
                    "The discount is more than 20% of the subtotal; give it a reason before sending the invoice.");
        }
        markSent(invoice);
    });
    return found;
}

/**
 * Sends each of the client's drafts that has at least one line, lowest id first, as {@link #send}
 * would; drafts with no lines, or whose discount needs a reason but has none, stay drafts.
 */
@Transactional
public void sendAllDrafts(Long clientId) {
    invoices.findByClientIdOrderByIdAsc(clientId).stream()
            .filter(invoice -> invoice.isDraft() && !invoice.getLines().isEmpty() && !invoice.discountLacksReason())
            .forEach(this::markSent);
}

/** Issues the draft today, due on the client's terms, and records it in the audit. */
private void markSent(Invoice invoice) {
    LocalDate issued = today.date();
    invoice.markSent(issued, dueDateFor(invoice.getClientId(), issued));
    invoices.saveAndFlush(invoice);
    audit.record("INVOICE_SENT id=" + invoice.getId() + " number=" + InvoiceNumber.of(invoice.getId())
            + " total=" + invoice.total(taxRate.percent()).toPlainString());
}

/**
 * Voids a sent invoice with no payments, and records it in the audit; empty if no such invoice. A
 * draft, an invoice already void, or one with any payment is refused.
 */
@Transactional
public Optional<Invoice> voidInvoice(Long invoiceId) {
}

/**
 * A discount to give: a percentage from 0 to 100 with at most two decimals, or a fixed amount
 * of money, not negative and to the cent. Exactly one of them. Optionally a cap, money not
 * negative and to the cent, that everything taken off, line discounts included, never comes to more than.
 * Optionally a reason, needed when the discount takes off more than a fifth of the subtotal.
 */
public record NewDiscount(
        @DecimalMin(value = "0", message = "The discount must be from 0 to 100 percent.")
        @DecimalMax(value = "100", message = "The discount must be from 0 to 100 percent.")
        @Digits(integer = 3, fraction = 2, message = "The discount can have at most two decimals.")
        BigDecimal discountPct,
        @DecimalMin(value = "0", message = "The discount amount cannot be negative.")
        @Digits(integer = 10, fraction = 2, message = "The discount amount can have at most two decimals.")
        BigDecimal discountAmount,
        @DecimalMin(value = "0", message = "The discount cap cannot be negative.")
        @Digits(integer = 10, fraction = 2, message = "The discount cap can have at most two decimals.")
        BigDecimal discountCap,
        @Size(max = 500, message = "The discount reason can be at most 500 characters.")
        String discountReason) {

    @AssertTrue(message = "Enter either a discount percentage or a discount amount.")
    public boolean isDiscountGiven() {
        return (discountPct == null) != (discountAmount == null);
    }
}

/**
 * A line to add: a description, a quantity above zero and a unit price of at least $0.01, and
 * whether it is tax exempt (taxable when left out), and its own discount percentage from 0 to 100

private final InvoiceService invoices;
private final TaxRate taxRate;
private final Today today;

public InvoiceController(InvoiceService invoices, TaxRate taxRate, Today today) {
    this.invoices = invoices;
    this.taxRate = taxRate;
    this.today = today;
}

private InvoiceSummary summary(Invoice i) {
    return InvoiceSummary.of(i, taxRate.percent(), invoices.paid(List.of(i)).get(i.getId()),
            invoices.paidOn(List.of(i)).get(i.getId()), today.date());
}

private InvoiceDetail detail(Invoice i) {
    return InvoiceDetail.of(i, taxRate.percent(), invoices.payments(i.getId()), today.date());
}

@GetMapping("/api/clients/{clientId}/invoices")
public List<InvoiceSummary> forClient(@PathVariable Long clientId) {
    BigDecimal rate = taxRate.percent();
    List<Invoice> list = invoices.forClient(clientId);
    Map<Long, BigDecimal> paid = invoices.paid(list);
    Map<Long, LocalDate> paidOn = invoices.paidOn(list);
    LocalDate on = today.date();
    return list.stream().map(i -> InvoiceSummary.of(i, rate, paid.get(i.getId()), paidOn.get(i.getId()), on)).toList();
}

/** The balance of each client that has a sent invoice; a client not listed owes nothing. Void invoices do not count. */
@GetMapping("/api/clients/balances")
public List<ClientBalance> balances() {
    BigDecimal rate = taxRate.percent();
    List<Invoice> sent = invoices.all().stream().filter(i -> !i.isDraft() && !i.isVoid()).toList();
    Map<Long, BigDecimal> paid = invoices.paid(sent);
    LocalDate on = today.date();
    Map<Long, BigDecimal[]> owed = new TreeMap<>();
    for (Invoice i : sent) {
        BigDecimal due = i.amountDue(paid.get(i.getId()), rate);
        BigDecimal[] sums = owed.computeIfAbsent(i.getClientId(),
                k -> new BigDecimal[] { BigDecimal.ZERO.setScale(2), BigDecimal.ZERO.setScale(2) });
        sums[0] = sums[0].add(due);
        if (i.statusWhenPaid(paid.get(i.getId()), rate, on) == InvoiceStatus.OVERDUE) {
            sums[1] = sums[1].add(due);
        }
    }
    return owed.entrySet().stream().map(e -> new ClientBalance(e.getKey(),
            e.getValue()[0].toPlainString(), e.getValue()[1].toPlainString())).toList();
}

@PostMapping("/api/clients/{clientId}/invoices")
@ResponseStatus(HttpStatus.CREATED)
public InvoiceSummary newDraft(@PathVariable Long clientId) {
    return invoices.newDraft(clientId).map(this::summary)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such client."));
}

/** Sends every draft of the client that has a line; answers the client's invoices with their new statuses. */
@PostMapping("/api/clients/{clientId}/invoices/send-drafts")
public List<InvoiceSummary> sendAllDrafts(@PathVariable Long clientId) {
    invoices.sendAllDrafts(clientId);
    return forClient(clientId);
}

@GetMapping("/api/invoices/{id}")
public InvoiceDetail open(@PathVariable Long id) {
    return invoices.find(id).map(this::detail)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such invoice."));
}

/** Opens the invoice with a typed number; a number whose check digit is wrong is refused. */
@GetMapping("/api/invoices/by-number/{number}")
public InvoiceDetail openByNumber(@PathVariable String number) {
    Long id = InvoiceNumber.idOf(number).orElseThrow(() -> new ResponseStatusException(
            HttpStatus.BAD_REQUEST, number.trim() + " is mistyped: check the invoice number."));
    return invoices.find(id).map(this::detail)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,
                    "There is no invoice " + number.trim() + "."));
}

@PostMapping("/api/invoices/{id}/lines")
@ResponseStatus(HttpStatus.CREATED)
public InvoiceDetail addLine(@PathVariable Long id, @Valid @RequestBody NewLine body) {
    return invoices.addLine(id, body.description().trim(), body.qty(), body.unitPrice(),
            Boolean.TRUE.equals(body.taxExempt()),
            body.discountPct() == null ? BigDecimal.ZERO : body.discountPct(), body.taxRate())
            .map(this::detail)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such invoice."));
}

@PutMapping("/api/invoices/{id}/lines/{lineId}")
public InvoiceDetail updateLine(@PathVariable Long id, @PathVariable Long lineId,
        @Valid @RequestBody NewLine body) {
    return invoices.updateLine(id, lineId, body.description().trim(), body.qty(), body.unitPrice(),
            Boolean.TRUE.equals(body.taxExempt()),
            body.discountPct() == null ? BigDecimal.ZERO : body.discountPct(), body.taxRate())
            .map(this::detail)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such line."));
}

@DeleteMapping("/api/invoices/{id}/lines/{lineId}")
public InvoiceDetail removeLine(@PathVariable Long id, @PathVariable Long lineId) {
    return invoices.removeLine(id, lineId)
            .map(this::detail)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such line."));
}

@PutMapping("/api/invoices/{id}/discount")
public InvoiceDetail setDiscount(@PathVariable Long id, @Valid @RequestBody NewDiscount body) {
    return invoices.setDiscount(id, body.discountPct(), body.discountAmount(), body.discountCap(), body.discountReason())
            .map(this::detail)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such invoice."));
}

@PostMapping("/api/invoices/{id}/duplicate")
@ResponseStatus(HttpStatus.CREATED)
public InvoiceDetail duplicate(@PathVariable Long id) {
    return invoices.duplicate(id)
            .map(this::detail)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such invoice."));
}

@PostMapping("/api/invoices/{id}/send")
public InvoiceDetail send(@PathVariable Long id) {
    return invoices.send(id)
            .map(this::detail)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such invoice."));
}

